// 2.60 « Réserve du jeu »: the game brings its own creations (migration 0118, generated by
// scripts/creations-reserve.mjs): 40 suits, 30 trails, 30 avatar frames and 30 victory effects,
// each one valid exactly as if an administrator had sent it to POST /admin/creations. They never
// replace a creation of an administrator, applying them twice adds nothing, and no player sees
// one before a challenge that has begun gives it (or a player won it); the administration tells
// them apart (« Réserve du jeu », where each one stands, the first challenge that gives it).

import { env } from "cloudflare:test";
import { beforeEach, describe, expect, it } from "vitest";
import { cleanTitleText, titleKey } from "../src/challengeRewards";
import { addDays, grantDuePrizes, periodBounds, periodOf, utcDate } from "../src/challenges";
import { FRAME_STYLES, TRAIL_LIFE_MS, TRAIL_STYLES, TRAIL_WIDTH, VICTORY_STYLES } from "../src/creations";
import { api, registerPlayer, seedAll, type TestPlayer } from "./helpers";

const V = "/api/v1";
const HASH = "2".repeat(64);
const RULES_HASH = "a".repeat(64);
const MIGRATION = "0118_creations_reserve.sql";

beforeEach(seedAll);

interface Row {
    id: number;
    kind: "suit" | "trail" | "frame" | "victory";
    name: string;
    name_key: string;
    suit_color: string | null;
    accent_color: string | null;
    scarf_color: string | null;
    color_a: string | null;
    color_b: string | null;
    style: string | null;
    width: number | null;
    life_ms: number | null;
    particles: number | null;
    created_by: string | null;
    archived: number;
    game_reserve: number;
}

/** The INSERTs of the migration again (its column is already there: the tests' database has every migration). */
async function insertReserve(): Promise<void> {
    const m = env.TEST_MIGRATIONS.find((x) => x.name === MIGRATION);
    expect(m, MIGRATION).toBeDefined();
    const inserts = m!.queries.filter((q) => /^INSERT INTO creations/im.test(q));
    expect(inserts.length).toBe(130);
    for (const q of inserts) await env.DB.prepare(q).run();
}

const rows = async (where = "1 = 1") => (await env.DB.prepare(`SELECT * FROM creations WHERE ${where} ORDER BY id`).all<Row>()).results;
const count = async (sql: string) => (await env.DB.prepare(sql).first<{ n: number }>())!.n;
const ctx = () => ({ env, requestId: "test", params: {}, url: new URL("https://test.invalid/"), ip: "test" }) as any;

async function admin(name = "NovaRider"): Promise<TestPlayer> {
    const p = await registerPlayer(name);
    await env.DB.prepare("UPDATE players SET role = 'admin' WHERE id = ?1").bind(p.id).run();
    return p;
}

/** The body an administrator would send for this creation (POST /admin/creations). */
function bodyOf(r: Row): Record<string, unknown> {
    if (r.kind === "suit") return { kind: "suit", name: r.name, colors: { suit: r.suit_color, accent: r.accent_color, scarf: r.scarf_color } };
    const keys = { trail: ["start", "end"], frame: ["border", "glow"], victory: ["main", "second"] }[r.kind];
    const body: Record<string, unknown> = { kind: r.kind, name: r.name, colors: { [keys[0]!]: r.color_a, [keys[1]!]: r.color_b }, style: r.style };
    if (r.kind === "trail") Object.assign(body, { width: r.width, life_ms: r.life_ms, particles: r.particles === 1 });
    return body;
}

/** What makes a creation: its kind, name, key and look. */
const lookOf = (r: Row) => ({
    kind: r.kind,
    name: r.name,
    name_key: r.name_key,
    suit_color: r.suit_color,
    accent_color: r.accent_color,
    scarf_color: r.scarf_color,
    color_a: r.color_a,
    color_b: r.color_b,
    style: r.style,
    width: r.width,
    life_ms: r.life_ms,
    particles: r.particles,
});

/** A challenge inserted directly (its period may have begun or be over). */
async function challenge(date: string): Promise<string> {
    const p = periodBounds("daily", periodOf("daily", date))!;
    const id = `daily-${p.period}`;
    await env.DB.prepare(
        `INSERT INTO challenges (id, kind, period, date, end_date, source, level_source, level_id, level_version, level_hash, level_title,
           hearts, slots, powers, stations, checkpoints, rules_hash, silver_ms, gold_ms, gold_no_damage, objective, created_at, updated_at)
         VALUES (?1, 'daily', ?2, ?3, ?4, 'admin', 'campaign', 'glacior_02', 1, ?5, 'Glacior', 3, 4, '[]', 1, 0, ?6, 90000, 70000, 1, 'speed', ?7, ?7)`,
    )
        .bind(id, p.period, p.start, p.end, HASH, RULES_HASH, new Date().toISOString())
        .run();
    return id;
}

const giveAt = (challengeId: string, position: number, r: Row, condition = "tier", value = 3) =>
    env.DB.prepare(
        "INSERT INTO challenge_reward_rules (challenge_id, position, reward_kind, reward_ref, condition, condition_value) VALUES (?1, ?2, ?3, ?4, ?5, ?6)",
    )
        .bind(challengeId, position, r.kind, `srv${r.kind}:${r.id}`, condition, value)
        .run();

describe("creations 2.60: the reserve of the game", () => {
    it("brings 40 suits, 30 trails, 30 frames and 30 victory effects, French names unique in their kind, styles and bounds of the lists", async () => {
        await insertReserve();
        const all = await rows();
        const per = (k: string) => all.filter((r) => r.kind === k).length;
        expect([per("suit"), per("trail"), per("frame"), per("victory")]).toEqual([40, 30, 30, 30]);
        const styles: Record<string, readonly string[]> = { trail: TRAIL_STYLES, frame: FRAME_STYLES, victory: VICTORY_STYLES };
        const keys = new Set<string>();
        for (const r of all) {
            expect(r, r.name).toMatchObject({ created_by: null, game_reserve: 1, archived: 0 });
            expect(cleanTitleText(r.name), r.name).toBe(r.name);
            expect([...r.name].length).toBeLessThanOrEqual(32);
            expect(r.name_key, r.name).toBe(titleKey(r.name));
            expect(keys.has(`${r.kind}:${r.name_key}`), r.name).toBe(false);
            keys.add(`${r.kind}:${r.name_key}`);
            if (r.kind === "suit") continue;
            expect(styles[r.kind], `${r.kind} ${r.name}`).toContain(r.style);
            if (r.kind === "trail") {
                expect(r.width!).toBeGreaterThanOrEqual(TRAIL_WIDTH.min);
                expect(r.width!).toBeLessThanOrEqual(TRAIL_WIDTH.max);
                expect(r.life_ms!).toBeGreaterThanOrEqual(TRAIL_LIFE_MS.min);
                expect(r.life_ms!).toBeLessThanOrEqual(TRAIL_LIFE_MS.max);
            }
        }
        // Every style of every kind is used (varied looks).
        for (const kind of ["trail", "frame", "victory"]) expect(new Set(all.filter((r) => r.kind === kind).map((r) => r.style)).size).toBe(styles[kind]!.length);
    });

    it("passes the administration's own checks, creation by creation, as if an administrator had made it", async () => {
        await insertReserve();
        const reserve = await rows();
        // The same creations sent by an administrator to a database without them: each one accepted as it is.
        await env.DB.prepare("DELETE FROM creations").run();
        const a = await admin();
        for (const [i, r] of reserve.entries()) {
            if (i % 50 === 0) await env.DB.prepare("DELETE FROM rate_limits").run();
            const res = await api("POST", `${V}/admin/creations`, { token: a.token, body: bodyOf(r) });
            expect(res.status, `${r.kind} « ${r.name} » ${JSON.stringify(res.body)}`).toBe(201);
            expect(res.body.data.creation).toMatchObject({ kind: r.kind, name: r.name, game_reserve: false, created_by: "NovaRider" });
        }
        const made = await rows();
        expect(made.map(lookOf)).toEqual(reserve.map(lookOf));
    }, 60_000);

    it("never replaces a creation of an administrator, and adds nothing the second time", async () => {
        const a = await admin();
        const suit = await api("POST", `${V}/admin/creations`, {
            token: a.token,
            body: { kind: "suit", name: "BRUME D'AETHRA", colors: { suit: "#101010", accent: "#202020", scarf: "#303030" } },
        });
        expect(suit.status).toBe(201);
        const trail = await api("POST", `${V}/admin/creations`, {
            token: a.token,
            body: { kind: "trail", name: "Sillage d’Aethra", colors: { start: "#101010", end: "#202020" }, style: "flame", width: 60, life_ms: 300, particles: false },
        });
        const frame = await api("POST", `${V}/admin/creations`, { token: a.token, body: { kind: "frame", name: "Gravitation", colors: { border: "#101010", glow: "#202020" }, style: "metal" } });
        await api("POST", `${V}/admin/creations/${frame.body.data.creation.id}/archive`, { token: a.token, body: { archived: true } });
        await insertReserve();
        // « Brume d'Aethra » (case aside) and « Gravitation » (archived) were the administrator's: kept as they were, no second one.
        expect(await rows("kind = 'suit' AND name_key = 'brume d''aethra'")).toEqual([
            expect.objectContaining({ id: suit.body.data.creation.id, name: "BRUME D'AETHRA", suit_color: "#101010", created_by: a.id, game_reserve: 0 }),
        ]);
        expect(await rows("kind = 'frame' AND name_key = 'gravitation'")).toEqual([
            expect.objectContaining({ id: frame.body.data.creation.id, style: "metal", archived: 1, created_by: a.id, game_reserve: 0 }),
        ]);
        // Another apostrophe is another name: the reserve's trail is added beside the administrator's.
        expect((await rows("kind = 'trail' AND name LIKE 'Sillage%'")).map((r) => [r.name, r.game_reserve])).toEqual([
            [trail.body.data.creation.name, 0],
            ["Sillage d'Aethra", 1],
        ]);
        const total = await count("SELECT COUNT(*) AS n FROM creations");
        expect(total).toBe(3 + 130 - 2);
        await insertReserve();
        expect(await count("SELECT COUNT(*) AS n FROM creations")).toBe(total);
    });

    it("stays out of everything a player reads until a challenge that has begun gives it, or a player won it", async () => {
        await insertReserve();
        const a = await admin();
        const player = await registerPlayer("Kestrel");
        const all = await rows();
        const pick = (kind: string, i = 0) => all.filter((r) => r.kind === kind)[i]!;
        expect((await api("GET", `${V}/creations`)).body.data.creations).toEqual([]);
        // The administration: « Réserve du jeu » (no author), never given yet.
        const listed = (await api("GET", `${V}/admin/creations`, { token: a.token })).body.data.creations;
        expect(listed).toHaveLength(130);
        for (const c of listed) expect(c).toMatchObject({ created_by: null, game_reserve: true, status: "reserve", given_by: null, uses: 0, owners: 0 });

        // Given at a coming challenge: « given » in the administration, still unknown to the players.
        const coming = addDays(utcDate(), 3);
        const trail = pick("trail");
        const set = await api("PUT", `${V}/admin/challenges/daily-${coming}/rewards`, {
            token: a.token,
            body: { rewards: [{ kind: "trail", ref: `srvtrail:${trail.id}`, condition: "tier", value: 3 }] },
        });
        expect(set.status, JSON.stringify(set.body)).toBe(200);
        const byId = async (id: number) => (await api("GET", `${V}/admin/creations`, { token: a.token })).body.data.creations.find((c: any) => c.id === id);
        expect(await byId(trail.id)).toMatchObject({
            status: "given",
            uses: 1,
            given_by: { id: `daily-${coming}`, kind: "daily", period: coming, date: coming, condition: "tier", value: 3 },
        });
        expect((await api("GET", `${V}/creations`)).body.data.creations).toEqual([]);
        expect((await api("GET", `${V}/challenges/daily-${coming}`)).status).toBe(404);

        // Given by today's challenge: its rewards are shown, so the players may see it (and only it).
        const today = await challenge(utcDate());
        const frame = pick("frame");
        await giveAt(today, 0, frame, "top", 10);
        const pub = (await api("GET", `${V}/creations`)).body.data.creations;
        expect(pub.map((c: any) => c.ref)).toEqual([`srvframe:${frame.id}`]);
        expect((await api("GET", `${V}/challenges/${today}`)).body.data.rewards).toEqual([expect.objectContaining({ kind: "frame", ref: `srvframe:${frame.id}` })]);

        // Archived, never given: « archived », and still not public.
        const victory = pick("victory");
        await api("POST", `${V}/admin/creations/${victory.id}/archive`, { token: a.token, body: { archived: true } });
        expect(await byId(victory.id)).toMatchObject({ status: "archived", game_reserve: true });
        expect((await api("GET", `${V}/creations`)).body.data.creations.map((c: any) => c.ref)).toEqual([`srvframe:${frame.id}`]);

        // A player cannot wear a creation of the reserve by its reference.
        const suit = pick("suit");
        const worn = await api("PUT", `${V}/players/me/cosmetics`, {
            token: player.token,
            body: { suit: `srvsuit:${suit.id}`, trail: `srvtrail:${trail.id}`, frame: "frame_simple", title: "title_none", victory: "victory_classic" },
        });
        expect([worn.body.data.cosmetics.suit.id, worn.body.data.cosmetics.trail.id]).toEqual(["suit_standard", "trail_none"]);
        expect((await api("GET", `${V}/players/me/rewards`, { token: player.token })).body.data.rewards).toEqual([]);
    });

    it("once won, is the player's like any reward: public, worn, and the reward says what it was won by", async () => {
        await insertReserve();
        const suit = (await rows("kind = 'suit'"))[3]!;
        const ended = await challenge(addDays(utcDate(), -3));
        await giveAt(ended, 0, suit, "tier", 3);
        const p = await registerPlayer("Aster");
        await env.DB.prepare(
            `INSERT INTO challenge_runs (id, challenge_id, player_id, attempt_id, time_ms, deaths, damage_taken, level_hash, rules_hash, game_version,
               tier, status, late, created_at) VALUES (?1, ?2, ?3, ?4, 60000, 0, 0, ?5, ?6, '2.60.0', 'gold', 'VERIFIED', 0, ?7)`,
        )
            .bind(crypto.randomUUID(), ended, p.id, crypto.randomUUID(), HASH, RULES_HASH, new Date().toISOString())
            .run();
        expect(await grantDuePrizes(ctx(), { limit: 50 })).toBe(1);
        const mine = (await api("GET", `${V}/players/me/rewards`, { token: p.token })).body.data.rewards;
        expect(mine).toEqual([
            expect.objectContaining({
                challenge: expect.objectContaining({ id: ended, kind: "daily", date: addDays(utcDate(), -3) }),
                kind: "suit",
                ref: `srvsuit:${suit.id}`,
                suit: { id: `srvsuit:${suit.id}`, name: suit.name, colors: { suit: suit.suit_color, accent: suit.accent_color, scarf: suit.scarf_color } },
                condition: "tier",
                value: 3,
            }),
        ]);
        const worn = await api("PUT", `${V}/players/me/cosmetics`, {
            token: p.token,
            body: { suit: `srvsuit:${suit.id}`, trail: "trail_none", frame: "frame_simple", title: "title_none", victory: "victory_classic" },
        });
        expect(worn.body.data.cosmetics.suit).toEqual({ id: `srvsuit:${suit.id}`, look: `srvsuit:${suit.id}`, name: suit.name });
        expect((await api("GET", `${V}/creations`)).body.data.creations.map((c: any) => c.ref)).toEqual([`srvsuit:${suit.id}`]);
        const a = await admin();
        const listed = (await api("GET", `${V}/admin/creations`, { token: a.token })).body.data.creations.find((c: any) => c.id === suit.id);
        expect(listed).toMatchObject({ status: "given", owners: 1, uses: 1, given_by: { id: ended, condition: "tier", value: 3 } });
    });
});
